import Foundation
import Testing
@testable import Tables

/// Frozen answer vectors, evaluated through the workbook engine. Expected answers
/// are constants from the existing documented examples and elementary closed forms;
/// they are never obtained by evaluating Tables' implementation. Numeric tolerance
/// accounts for the last printed decimal, with a separate relative roundoff bound.
struct ComplexAnswer: Sendable {
    let real: Double
    let imaginary: Double
}

struct FormulaAnswerCase: Sendable, CustomTestStringConvertible {
    let function: String
    let formula: String
    let expected: CellValue
    var absoluteTolerance: Double = 0
    var relativeTolerance: Double = 1e-12
    var entries: [String: String] = [:]
    var expectedRows: [[CellValue]]? = nil
    var complexComponents: ComplexAnswer? = nil
    var testDescription: String { formula }
}

